// ════════════════════════════════════════════════════════════════════════
//  Биоимпланты и химия/алхимия Друкхари (Warhammer DBC).
//  Импланты → компендиум "implants", категория "bioimplant",
//  папка «Биоимпланты (Друкхари)».
//  Химия → компендиум "chemistry": яды (poison) и алхимические
//  стимуляторы (narcotic). DRUKHARI_BIOIMPLANTS питает каталог Мастерской
//  (apps/craft-workshop.mjs); своего компендиум-генератора у файла нет.
//
//  Эффекты записаны текстом (effect / afterEffect) — большинство правил
//  биоимплантов нарративные и не ложатся в поля движка. Качество (Poor/Good/
//  Best.Q) и вариации указаны в тексте эффекта.
// ════════════════════════════════════════════════════════════════════════

const IMG = "icons/svg/item-bag.svg";
const FX0 = { charBonusStat: "", charBonusValue: 0, armourAll: 0, fearRating: 0, sizeMod: 0 };
const DRUKHARI_BOOK = "Книга Аэльдари: Ответвления, БИОИМПЛАНТЫ (стр. 149)";

// Биоимплант. B(name, rarity, effect, description, effects)
const B = (name, rarity, effect, description = "", effects = {}) => ({
  name, type: "implant", img: IMG,
  system: {
    category: "bioimplant", quality: "common", installed: "",
    description: `R ${rarity}. ${description}`.trim(),
    effect, bookSource: DRUKHARI_BOOK, effects: { ...FX0, ...effects }
  }
});

// Подпапки в компендиуме: «Биоимпланты (Друкхари)» → группа.
const group = (folder, arr) => arr.map(b => ({ ...b, folderPath: ["Биоимпланты (Друкхари)", folder] }));

