// Яды Друкхари игнорируют таланты снижения ядов, естественный и психический
// иммунитет к ядам (но не иммунитет демонов/чистых машин).
const DPOISON = (name, rarity, vector, effect, description) => ({
  name, type: "drug", img: IMG,
  system: {
    description, drugCategory: "poison", deliveryMethod: vector, availability: rarity, quantity: 1,
    effect, hasAfterEffect: false
  }
});

// Алхимические стимуляторы: только для друкхари (для мон-кай — Яд Best.Q),
// Токсичность 2, действуют 10 минут, без Зависимости.
const ALCH_POST = "Пост-эффект: по окончании действия персонаж платит R×5 Боли (не единоразово), иначе не может пользоваться механикой Боли; и получает R уровней Усталости. Токсичность 2. Работает в Нуль-Поле.";
const DALCH = (name, rarity, base, sl, occult, xeno) => ({
  name, type: "drug", img: IMG,
  system: {
    description: `Алхимия Друкхари (R ${rarity}). Действует 10 минут, только на друкхари (для мон-кай — Яд Best.Q). Требует Рецепт (R+1).`,
    drugCategory: "narcotic", deliveryMethod: "injection", availability: rarity, quantity: 1,
    effect: `Базовый: ${base}. | Trade (Chymist)+20: ${sl}. | Scholastic Lore (Occult)+20: ${occult}. | Forbidden Lore (Xenobiology)+20: ${xeno}`,
    hasAfterEffect: true, afterEffect: ALCH_POST
  }
});

